from src.ml_lab import render_ml_lab

st.set_page_config(page_title="Data Science & ML Bootcamp", layout="wide", initial_sidebar_state="collapsed")

if 'current_strategy' not in st.session_state:
    st.session_state.current_strategy = "bootcamp_day1_4"

st.markdown(get_custom_css(st.session_state.current_strategy), unsafe_allow_html=True)

# 메인 페이지 헤더
st.markdown(f'''
<div class="custom-header">
    <div class="header-top-row">
        <img src="data:image/jpeg;base64," class="header-logo">
        <h2 class="header-title">Data Science & ML Bootcamp</h2>
    </div>
    <div class="header-subtitle">Python, Pandas, Scikit-learn을 활용한 데이터 분석 및 머신러닝 실전 훈련</div>
</div>
''', unsafe_allow_html=True)

# 상단 글로벌 모드 스위처
# 심플한 토글 스위치로 모드 변경 (st.radio 충돌 원천 차단)
is_comp_mode = st.toggle("🔥 심화 마스터 버전", value=(st.session_state.current_strategy == "comprehensive"), help="심화 마스터 버전: Pandas, Scikit-learn의 핵심 개념과 고급 테크닉, 시각화를 모두 포함하는 확장 스터디 모드입니다.")
selected_mode = "comprehensive" if is_comp_mode else "bootcamp_day1_4"

if st.session_state.current_strategy != selected_mode:
    st.session_state.current_strategy = selected_mode
    # 전략이 바뀌면 진행 상태 초기화
    st.session_state.s_current_q = generate_single_quiz(selected_mode)
    st.session_state.s_total_solved = 0
    st.session_state.s_total_correct = 0
    st.session_state.exam_state = 'landing'
    st.session_state.e_quizzes = generate_exam_quizzes(selected_mode)
    st.rerun()

tabs = st.tabs(["📚 학습", "🚨 모의고사", "🏆 랭킹", "🧪 ML 실험실"])

with tabs[0]:
    remove_timer()
    
    if 's_total_solved' not in st.session_state:
        st.session_state.s_total_solved = 0
        st.session_state.s_total_correct = 0
        st.session_state.s_current_q = generate_single_quiz(st.session_state.current_strategy, st.session_state.get("s_topic", "전체 랜덤"))
        st.session_state.s_attempts = 0
        st.session_state.s_show_exp = False
        st.session_state.s_correct = False

    if 's_topic' not in st.session_state:
        st.session_state.s_topic = "전체 랜덤"

    available_topics = get_available_topics(st.session_state.current_strategy)
    
    tool_col1, tool_col2 = st.columns([1, 1], gap="large", vertical_alignment="bottom")
    with tool_col1:
        selected_topic = st.selectbox("🎯 집중 학습할 주제", available_topics, index=available_topics.index(st.session_state.s_topic) if st.session_state.s_topic in available_topics else 0)
    
    if selected_topic != st.session_state.s_topic:
        st.session_state.s_topic = selected_topic
        st.session_state.s_current_q = generate_single_quiz(st.session_state.current_strategy, selected_topic)
        st.session_state.s_attempts = 0
        st.session_state.s_show_exp = False
        st.session_state.s_correct = False
        st.rerun()

    with tool_col2:
        acc = (st.session_state.s_total_correct / st.session_state.s_total_solved * 100) if st.session_state.s_total_solved > 0 else 0
        st.markdown(f'''
        <div class="hud-container" style="margin-top: 0; margin-bottom: 1.5rem; justify-content: flex-end;">
            <div class="hud-badge">🔥 총 완료: <span>{st.session_state.s_total_solved}</span> 문제</div>
            <div class="hud-badge">🎯 1트 성공률: <span>{acc:.1f}</span> %</div>
        </div>
        ''', unsafe_allow_html=True)
    
    q = st.session_state.s_current_q
    
    study_col1, study_col2 = st.columns([1, 1], gap="large")
    
    with study_col1:
        with st.container(border=True):
            st.markdown(f"**Q. {q['topic']}** (객관식 4지선다)")
            st.markdown(f"{q['question']}")
            user_ans = st.radio("보기 선택", options=q['choices'], label_visibility="hidden", key=f"s_ans_endless", index=None)

    with study_col2:
        if st.session_state.s_show_exp:
            is_corr = st.session_state.s_correct
            result_color = "#10b981" if is_corr else "#ef4444"
            result_bg = "rgba(16,185,129,0.05)" if is_corr else "rgba(239,68,68,0.05)"
            result_border = "rgba(16,185,129,0.4)" if is_corr else "rgba(239,68,68,0.4)"
            result_title = f"<h2 style='color: {result_color}; margin: 0 0 1rem 0; font-size: 2.2rem; font-weight: 800;'>{'정답입니다!' if is_corr else '틀렸습니다.'}</h2>"
        
            exp_html = f'''
            <div style="background: {result_bg}; border: 2px solid {result_border}; border-radius: 20px; padding: 2rem; margin-bottom: 0; box-shadow: 0 12px 32px rgba(0,0,0,0.05);">
                {result_title}
                <h4 style="margin-top:0.5rem; margin-bottom:1rem; color:#3b82f6; font-size:1.2rem;">💡 정답 및 해설</h4>
                <div style="background:#1e293b; padding:1.2rem; border-radius:12px; margin-bottom:1.2rem; font-family:'JetBrains Mono', monospace; color:#10b981; font-size:1.15rem; font-weight:700; line-height:1.4;">
                    {q['expected']}
                </div>
                <p style="font-weight:600; font-size:1.1rem; color:#1e293b; word-break:keep-all; line-height:1.7;">{q['explanation']}</p>
            </div>
            '''
            st.markdown(exp_html, unsafe_allow_html=True)
        else:
            if st.session_state.s_attempts > 0:
                st.error(f"❌ 틀렸습니다. (남은 기회: {3 - st.session_state.s_attempts}회)")
                exp_text = q['explanation']
                if st.session_state.s_attempts == 1:
                    hint = exp_text[:max(10, len(exp_text)//4)] + "..."
                    st.warning(f"💡 [힌트 1단계] {hint}")
                elif st.session_state.s_attempts == 2:
                    hint = exp_text[:max(20, len(exp_text)*2//3)] + "..."
                    st.warning(f"💡 [힌트 2단계] {hint}")
            else:
                st.markdown('''
                <div style="display:flex; flex-direction:column; align-items:center; justify-content:center; height:100%; min-height: 250px; opacity: 0.3; background: rgba(0,0,0,0.02); border-radius: 16px; border: 2px dashed rgba(0,0,0,0.1);">
                    <div style="font-size: 4rem; margin-bottom: 1rem; filter: grayscale(1);">🙈</div>
                    <p style="font-weight:700; font-size: 1.2rem; text-align:center;">문제를 풀고 나면<br>이곳에 정답과 해설이 나타납니다.</p>
                </div>
                ''', unsafe_allow_html=True)

    st.markdown("<div style='margin-top: 1.5rem;'></div>", unsafe_allow_html=True)
    
    # Dedicated button row for perfect horizontal alignment
    btn_col1, btn_col2 = st.columns([1, 1], gap="large")
    
    with btn_col1:
        if not st.session_state.s_show_exp:
            sub_col1, sub_col2 = st.columns(2)
            with sub_col1:
                submit_clicked = st.button("정답 제출", type="primary", key="btn_study_submit", use_container_width=True)
            with sub_col2:
                pass_clicked = st.button("패스 (정답 보기)", key="btn_study_pass", use_container_width=True)
                
            if submit_clicked:
                if not user_ans:
                    st.warning("보기를 선택해주세요.")
                else:
                    is_correct = (user_ans == q['expected'])
                    if is_correct:
                        st.session_state.s_correct = True
                        st.session_state.s_show_exp = True
                        st.session_state.s_total_solved += 1
                        if st.session_state.s_attempts == 0:
                            st.session_state.s_total_correct += 1
                    else:
                        st.session_state.s_attempts += 1
                        if st.session_state.s_attempts >= 3:
                            st.session_state.s_correct = False
                            st.session_state.s_show_exp = True
                            st.session_state.s_total_solved += 1
                st.rerun()
                
            if pass_clicked:
                st.session_state.s_correct = False
                st.session_state.s_show_exp = True
                st.session_state.s_total_solved += 1
                st.session_state.s_attempts += 1
                st.rerun()
        else:
            sub_col1, sub_col2 = st.columns(2)
            with sub_col1:
                st.button("제출 완료", disabled=True, use_container_width=True)
            with sub_col2:
                st.button("결과 확인", disabled=True, use_container_width=True)

    with btn_col2:
        if st.session_state.s_show_exp:
            if st.button("다음 문제 풀기 (Endless) 🚀", type="primary", key="btn_study_next", use_container_width=True):
                st.session_state.s_current_q = generate_single_quiz(st.session_state.current_strategy, st.session_state.get("s_topic", "전체 랜덤"))
                st.session_state.s_attempts = 0
                st.session_state.s_show_exp = False
                st.rerun()


with tabs[1]:
    if 'exam_state' not in st.session_state:
        st.session_state.exam_state = 'landing'
        st.session_state.e_quizzes = generate_exam_quizzes(st.session_state.current_strategy)
        st.session_state.e_score = 0
        st.session_state.e_user_answers = []
        st.session_state.exam_name = ""
        st.session_state.exam_start_time = 0
        st.session_state.exam_end_time = 0

    if st.session_state.exam_state == 'landing':
        remove_timer()
        with st.container(border=True):
            st.markdown('''
            <div style="text-align: center; padding: 1rem;">
                <h3 style="margin-bottom:0.5rem; color:#0f172a;">🚨 실전 모의고사</h3>
                <p style="color: #64748b; font-size:0.9rem;">20문항 (객관식 20) | 제한 시간 40분</p>
            </div>
            ''', unsafe_allow_html=True)
            
            candidate_name = st.text_input("수험자 이름(ID):", placeholder="홍길동", label_visibility="collapsed")
            
            if st.button("▶️ 모의고사 응시 시작", type="primary", use_container_width=True):
                if candidate_name.strip():
                    st.session_state.exam_name = candidate_name.strip()
                    st.session_state.e_quizzes = generate_exam_quizzes(st.session_state.current_strategy)
                    st.session_state.exam_start_time = time.time()
                    st.session_state.exam_state = 'running'
                    st.rerun()
                else:
                    st.warning("이름을 입력하세요.")

    elif st.session_state.exam_state == 'running':
        inject_timer(2400, st.session_state.exam_start_time)
        st.markdown(f"수험자: **{st.session_state.exam_name}** 님")
        
        with st.form("exam_form"):
            user_answers = []
            for i, q in enumerate(st.session_state.e_quizzes):
                st.markdown(f"**Q{i+1:02d}. {q['topic']}** " + ("(주관식 ⌨️)" if q['type'] == 'text' else "(객관식 🖱️)"))
                st.markdown(f"{q['question']}")
                
                if q['type'] == 'radio':
                    ans = st.radio(f"보기 {i+1}", options=q['choices'], label_visibility="hidden", key=f"exam_ans_{i}", index=None)
                else:
                    ans = st.text_input(f"답안 {i+1}", placeholder="코드를 직접 타이핑하세요", label_visibility="hidden", key=f"exam_ans_{i}")
                    
                user_answers.append(ans)
                st.markdown("---")
            
            if st.form_submit_button("최종 답안 제출", type="primary", use_container_width=True):
                st.session_state.exam_end_time = time.time()
                score = 0
                for i, q in enumerate(st.session_state.e_quizzes):
                    if user_answers[i] and user_answers[i] == q['expected']:
                        score += 1
                st.session_state.e_score = score
                st.session_state.e_user_answers = user_answers
                save_score(st.session_state.exam_name, st.session_state.e_score, st.session_state.current_strategy)
                st.session_state.exam_state = 'finished'
                st.rerun()

    elif st.session_state.exam_state == 'finished':
        remove_timer()
        if not st.session_state.get('exam_balloons_shown', False):
            st.balloons()
            st.session_state.exam_balloons_shown = True
        elapsed_sec = int(st.session_state.exam_end_time - st.session_state.exam_start_time)
        m, s = divmod(elapsed_sec, 60)
        
        st.success("🎊 시험이 종료되었습니다.")
        
        col1, col2, col3 = st.columns(3)
        col1.metric(label="수험자", value=st.session_state.exam_name)
        col2.metric(label="점수", value=f"{st.session_state.e_score}/20")
        col3.metric(label="시간", value=f"{m}분 {s}초")
        
        with st.expander("상세 성적표 보기"):
            for i, q in enumerate(st.session_state.e_quizzes):
                u_ans = st.session_state.e_user_answers[i]
                if not u_ans:
                    is_cor = False
                else:
                    is_cor = (u_ans == q['expected'])
                    
                css_class = "report-correct" if is_cor else "report-wrong"
                st.markdown(f'''<div class="{css_class}">
                    <strong>Q{i+1:02d}. {q['topic']}</strong><br>
                    내 답: <code>{u_ans if u_ans else "미입력"}</code><br>
                    정답: <code>{q['expected']}</code>
                </div>''', unsafe_allow_html=True)
            
        if st.button("🔄 새로운 모의고사 응시", use_container_width=True):
            st.session_state.exam_state = 'landing'
            st.session_state.e_score = 0
            st.session_state.e_user_answers = []
            st.rerun()

with tabs[2]:
    remove_timer()
    st.markdown("<h3 style='text-align: center; margin-bottom: 1rem;'>🏆 명예의 전당</h3>", unsafe_allow_html=True)
    
    lb = load_leaderboard()
    
    filtered_lb = []
    for row in lb:
        raw_name = row['name']
        if "###" in raw_name:
            parsed_name, strategy = raw_name.split("###", 1)
        else:
            parsed_name, strategy = raw_name, "bootcamp_day1_4"
            
        if strategy == st.session_state.current_strategy:
            row['display_name'] = parsed_name
            filtered_lb.append(row)
            
    if not filtered_lb:
        st.info("해당 과정의 랭킹이 없습니다. 첫 번째 랭커에 도전하세요!")
    else:
        df_lb = pd.DataFrame(filtered_lb)
        df_lb = df_lb.sort_values(by='score', ascending=False).reset_index(drop=True)
        
        df_lb.index = df_lb.index + 1
        
        # 날짜 포맷
        if 'created_at' in df_lb.columns:
            df_lb['date_str'] = pd.to_datetime(df_lb['created_at']).dt.strftime('%m-%d %H:%M')
        elif 'date' in df_lb.columns:
            df_lb['date_str'] = pd.to_datetime(df_lb['date']).dt.strftime('%m-%d %H:%M')
        else:
            df_lb['date_str'] = "-"
            
        if 'time_sec' not in df_lb.columns:
            df_lb['time_sec'] = 0
        df_lb['time_sec'] = df_lb['time_sec'].fillna(0).astype(int).astype(str) + "초"
        
        display_df = df_lb[['display_name', 'score', 'time_sec', 'date_str']]
        display_df.columns = ['유저 닉네임', '획득 점수 (점)', '소요 시간', '달성일']
        
        st.dataframe(
            display_df,
            use_container_width=True,
            column_config={
                "유저 닉네임": st.column_config.TextColumn("유저 닉네임", width="medium"),
                "획득 점수 (점)": st.column_config.NumberColumn("획득 점수 (점)", format="%d 점"),
                "소요 시간": st.column_config.TextColumn("소요 시간", width="small"),
                "달성일": st.column_config.TextColumn("달성일", width="medium")
            }
        )
with tabs[3]:
    remove_timer()
    with st.container(border=False):
        render_ml_lab()
